function validate([nums, queries]) {
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100,000 values.';
  if (queries.length < 1 || queries.length > nums.length) return 'queries needs between 1 and nums.length entries.';
  if (nums.some(v => v < 1 || v > 1000000)) return 'Each value of nums is between 1 and 10^6.';
  if (queries.some(q => q < 0 || q >= nums.length)) return 'Each query is an index of nums.';
  return null;
}

