function solveQueries(nums, queries) {
  const n = nums.length;
  const positions = new Map();
  for (let i = 0; i < n; i++) {
    if (!positions.has(nums[i])) {
      positions.set(nums[i], []);
    }
    positions.get(nums[i]).push(i);
  }
  const closest = new Array(n).fill(-1);
  for (const list of positions.values()) {
    const m = list.length;
    if (m === 1) {
      continue;
    }
    for (let p = 0; p < m; p++) {
      const index = list[p];
      const before = list[(p - 1 + m) % m];
      const after = list[(p + 1) % m];
      const back = (index - before + n) % n;
      const ahead = (after - index + n) % n;
      closest[index] = Math.min(back, ahead);
    }
  }
  const answer = [];
  for (const query of queries) {
    answer.push(closest[query]);
  }
  return answer;
}

