function solveQueries(nums, queries) {
  // For each query, measure the circular distance to every other index with the same value.
  const n = nums.length;
  return queries.map(i => {
    let best = -1;
    for (let j = 0; j < n; j++) {
      if (j === i || nums[j] !== nums[i]) continue;
      const gap = Math.abs(i - j);
      const distance = Math.min(gap, n - gap);
      if (best === -1 || distance < best) best = distance;
    }
    return best;
  });
}

