function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 2000 : int(1, 10);
  // Few distinct values make many repeats; a wide range leaves most values unique.
  const top = size === 'large' ? [50, 1000, 1000000][int(0, 2)] : [2, 4, 1000000][int(0, 2)];
  const nums = Array.from({ length: n }, () => int(1, top));
  const count = size === 'large' ? n : int(1, n);
  const queries = Array.from({ length: count }, () => int(0, n - 1));
  return [nums, queries];
}
